window.LESSON_DATA = {"schemaVersion":"2.0.0","version":"2.0.0","buildDate":"2026-08-01","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":2,"title":"Functions"},"lesson":{"number":"2.3","slug":"polynomial-rational-models","title":"Polynomial and Rational Models","subtitle":"Use zeros, end behaviour, asymptotes and variation structure to interpret non-linear models and their limitations.","syllabus_focus":"Polynomial and rational behaviour, direct and inverse variation, zeros, domains, asymptotes and technology-supported model selection.","skill_keys":["IBAI.U2.POLY_RATIONAL"],"objectives":["Interpret polynomial degree, zeros and end behaviour from equations and graphs.","Use factors and multiplicity to connect algebraic structure with graph behaviour.","Determine domains and asymptotes of rational models and interpret them contextually.","Recognize direct, inverse and power variation and use technology to estimate parameters."],"vocab":["polynomial","degree","leading coefficient","zero","multiplicity","end behaviour","rational function","vertical asymptote","horizontal asymptote","variation"],"technology":"Use tables and graphing tools to locate zeros and asymptotes, then verify each feature from the algebraic structure and intended domain.","inquiry":"A response rises, levels, and then falls, while another quantity changes rapidly near a forbidden input. What model structures explain these different behaviours?"},"slides":[{"section":"Launch","title":"Polynomial and Rational Models","html":"<div class=\"cover-grid\"><div><div class=\"cover-kicker\">IB Mathematics: Applications and Interpretation SL</div><div class=\"cover-number\">2.3</div><h1>Polynomial and Rational Models</h1><p class=\"cover-subtitle\">Use zeros, end behaviour, asymptotes and variation structure to interpret non-linear models and their limitations.</p><div class=\"pill-row\"><span>Inquiry</span><span>Technology</span><span>Modelling</span><span>Interpretation</span><span>Evaluation</span></div><button class=\"primary-btn route-jump\" data-go=\"practice\">Open Practice Studio</button></div><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"polynomial and rational behaviour\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M35 190 C95 35,155 230,225 78 S355 50,480 200\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"225\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">polynomial and rational behaviour</text>\n    </svg></div></div>","kind":"cover","eyebrow":"Unit 2 · Functions"},{"section":"Launch","title":"Inquiry launch","html":"<div class=\"launch-panel\"><h2>Start with a decision</h2><p>A response rises, levels, and then falls, while another quantity changes rapidly near a forbidden input. What model structures explain these different behaviours?</p><textarea class=\"student-note\" data-note=\"inquiry\" placeholder=\"Write an initial model, assumption or question before continuing.\"></textarea></div>","kind":"content","eyebrow":"Think before calculating"},{"section":"Launch","title":"Learning outcomes","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"obj-2.3-0\"><span>Interpret polynomial degree, zeros and end behaviour from equations and graphs.</span></label><label><input type=checkbox data-reflect=\"obj-2.3-1\"><span>Use factors and multiplicity to connect algebraic structure with graph behaviour.</span></label><label><input type=checkbox data-reflect=\"obj-2.3-2\"><span>Determine domains and asymptotes of rational models and interpret them contextually.</span></label><label><input type=checkbox data-reflect=\"obj-2.3-3\"><span>Recognize direct, inverse and power variation and use technology to estimate parameters.</span></label></div>","kind":"content","eyebrow":"By the end"},{"section":"Launch","title":"Diagnostic checkpoint","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Prior knowledge</h2><p>Coordinate axes, substitution, equation solving, percentage change and clear use of units.</p></article><article class=\"focus-card\"><h2>Quick self-check</h2><p>Can you distinguish an input restriction from a graphing-window choice? Can you explain what a parameter means in context?</p></article></div><textarea class=\"student-note\" data-note=\"diagnostic\" placeholder=\"Record one strength and one question.\"></textarea>","kind":"content","eyebrow":"Activate prior learning"},{"section":"Launch","title":"Vocabulary and notation","html":"<div class=\"vocab-grid\"><span class=vocab-chip>polynomial</span><span class=vocab-chip>degree</span><span class=vocab-chip>leading coefficient</span><span class=vocab-chip>zero</span><span class=vocab-chip>multiplicity</span><span class=vocab-chip>end behaviour</span><span class=vocab-chip>rational function</span><span class=vocab-chip>vertical asymptote</span><span class=vocab-chip>horizontal asymptote</span><span class=vocab-chip>variation</span></div><div class=\"callout\"><b>Communication standard:</b> define every variable, include units, and distinguish an exact result from a rounded interpretation.</div>","kind":"content","eyebrow":"Language matters"},{"section":"Launch","title":"IB command terms","html":"<div class=\"command-grid\"><div><b>Calculate / Find</b><span>Show relevant stages and a defensible final value.</span></div><div><b>Determine</b><span>Obtain the only possible answer.</span></div><div><b>Interpret</b><span>Connect the mathematics to variables, units and context.</span></div><div><b>Explain / Justify</b><span>Give mathematical reasons, not only a conclusion.</span></div><div><b>Evaluate / Comment</b><span>Judge validity using evidence, assumptions and limitations.</span></div><div><b>Construct / Sketch</b><span>Communicate an accurate, labelled representation.</span></div></div>","kind":"content","eyebrow":"Answer the verb"},{"section":"Launch","title":"Technology contract","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Purpose</h2><p>Use tables and graphing tools to locate zeros and asymptotes, then verify each feature from the algebraic structure and intended domain.</p></article><article class=\"focus-card\"><h2>Evidence to record</h2><p>Window/domain, equation or list entered, relevant output, units, rounding and a sentence interpreting the result.</p></article></div>","kind":"content","eyebrow":"GDC is a reasoning tool"},{"section":"Launch","title":"Lesson pathway","html":"<div class=\"workflow\"><div><b>1</b><span>Learn concepts through representations.</span></div><div><b>2</b><span>Investigate with technology.</span></div><div><b>3</b><span>Practise across four levels.</span></div><div><b>4</b><span>Complete IB tasks and a timed quiz.</span></div><div><b>5</b><span>Review evidence and mark completion.</span></div></div>","kind":"content","eyebrow":"Learn · practise · master"},{"section":"Concept cycle 1","title":"Degree and end behaviour","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>For a polynomial, the leading term controls behaviour for large positive and negative inputs. Degree parity and leading-coefficient sign determine the two ends.</p></article><div class=\"formula-panel\">\\[f(x)=a_nx^n+\\cdots\\]</div></div>","kind":"content","eyebrow":"1 of 8"},{"section":"Concept cycle 1","title":"Degree and end behaviour: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"polynomial and rational behaviour\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M35 190 C95 35,155 230,225 78 S355 50,480 200\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"225\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">polynomial and rational behaviour</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for degree and end behaviour?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 1","title":"Worked example: Degree and end behaviour","html":"<div class=\"worked\"><h2>Describe the end behaviour of f(x)=−3x⁵+2x²−7.</h2><ol class=\"method\"><li>The leading term is −3x⁵.</li><li>Odd degree gives opposite ends.</li><li>As x→∞, f(x)→−∞; as x→−∞, f(x)→∞.</li></ol><div class=\"formula-panel\">\\[f(x)=a_nx^n+\\cdots\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 1","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Describe the end behaviour of g(x)=2x⁴−9x+1.</b></div><textarea class=\"student-note tall\" data-note=\"turn-1\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">Even degree and positive leading coefficient: both ends rise to ∞.</div></details></div>","kind":"content","eyebrow":"Degree and end behaviour"},{"section":"Concept cycle 1","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“The constant term controls end behaviour.”</p><h3>Repair</h3><p>For large |x|, the highest-power term dominates.</p></div></div>","kind":"content","eyebrow":"Degree and end behaviour"},{"section":"Concept cycle 2","title":"Zeros and factors","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>If f(r)=0, then x−r is a factor. Real zeros are x-intercepts when they lie in the model domain.</p></article><div class=\"formula-panel\">\\[f(x)=a(x-r_1)(x-r_2)\\cdots\\]</div></div>","kind":"content","eyebrow":"2 of 8"},{"section":"Concept cycle 2","title":"Zeros and factors: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"polynomial and rational behaviour\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M35 190 C95 35,155 230,225 78 S355 50,480 200\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"225\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">polynomial and rational behaviour</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for zeros and factors?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 2","title":"Worked example: Zeros and factors","html":"<div class=\"worked\"><h2>Find the zeros of f(x)=(x+4)(2x−3)(x−1).</h2><ol class=\"method\"><li>Set each factor equal to zero.</li><li>x=−4, x=3/2, x=1.</li><li>These are the graph’s x-intercepts.</li></ol><div class=\"formula-panel\">\\[f(x)=a(x-r_1)(x-r_2)\\cdots\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 2","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Factor x³−4x and state all zeros.</b></div><textarea class=\"student-note tall\" data-note=\"turn-2\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">x(x−2)(x+2); zeros −2,0,2.</div></details></div>","kind":"content","eyebrow":"Zeros and factors"},{"section":"Concept cycle 2","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“A factor x+r gives root r.”</p><h3>Repair</h3><p>Set the factor equal to zero: x+r=0 gives x=−r.</p></div></div>","kind":"content","eyebrow":"Zeros and factors"},{"section":"Concept cycle 3","title":"Multiplicity and crossing behaviour","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>A zero of odd multiplicity usually crosses the axis; a zero of even multiplicity touches and turns. Greater multiplicity flattens the graph near the zero.</p></article><div class=\"formula-panel\">\\[f(x)=(x-2)^2(x+1)^3\\]</div></div>","kind":"content","eyebrow":"3 of 8"},{"section":"Concept cycle 3","title":"Multiplicity and crossing behaviour: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"polynomial and rational behaviour\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M35 190 C95 35,155 230,225 78 S355 50,480 200\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"225\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">polynomial and rational behaviour</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for multiplicity and crossing behaviour?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 3","title":"Worked example: Multiplicity and crossing behaviour","html":"<div class=\"worked\"><h2>Describe the graph near x=2 and x=−1.</h2><ol class=\"method\"><li>x=2 has even multiplicity 2, so the graph touches.</li><li>x=−1 has odd multiplicity 3, so it crosses.</li><li>The cubic multiplicity produces a flatter crossing.</li></ol><div class=\"formula-panel\">\\[f(x)=(x-2)^2(x+1)^3\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 3","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>How does y=(x+5)⁴(x−3) behave at its zeros?</b></div><textarea class=\"student-note tall\" data-note=\"turn-3\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">It touches at x=−5 and crosses at x=3.</div></details></div>","kind":"content","eyebrow":"Multiplicity and crossing behaviour"},{"section":"Concept cycle 3","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“Every zero is a crossing.”</p><h3>Repair</h3><p>Multiplicity determines whether the sign changes.</p></div></div>","kind":"content","eyebrow":"Multiplicity and crossing behaviour"},{"section":"Concept cycle 4","title":"Cubic models and turning behaviour","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>A cubic can model growth followed by decline, but not every cubic has two turning points. Technology can locate roots and extrema.</p></article><div class=\"formula-panel\">\\[P(t)=0.08t^3-1.4t^2+5t+12\\]</div></div>","kind":"content","eyebrow":"4 of 8"},{"section":"Concept cycle 4","title":"Cubic models and turning behaviour: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"polynomial and rational behaviour\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M35 190 C95 35,155 230,225 78 S355 50,480 200\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"225\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">polynomial and rational behaviour</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for cubic models and turning behaviour?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 4","title":"Worked example: Cubic models and turning behaviour","html":"<div class=\"worked\"><h2>Explain why a cubic may be more flexible than a quadratic for a response that rises, falls and rises again.</h2><ol class=\"method\"><li>A quadratic has at most one turning point.</li><li>A cubic may have two turning points.</li><li>The domain must still reflect the context.</li></ol><div class=\"formula-panel\">\\[P(t)=0.08t^3-1.4t^2+5t+12\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 4","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>State the maximum number of turning points of a degree-5 polynomial.</b></div><textarea class=\"student-note tall\" data-note=\"turn-4\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">At most 4.</div></details></div>","kind":"content","eyebrow":"Cubic models and turning behaviour"},{"section":"Concept cycle 4","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“Degree n means exactly n−1 turning points.”</p><h3>Repair</h3><p>n−1 is a maximum, not a guarantee.</p></div></div>","kind":"content","eyebrow":"Cubic models and turning behaviour"},{"section":"Concept cycle 5","title":"Rational domains and vertical asymptotes","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>A rational function is undefined where its denominator is zero. A non-cancelled zero of the denominator usually gives a vertical asymptote.</p></article><div class=\"formula-panel\">\\[R(x)=\\frac{3x+2}{x-4}\\]</div></div>","kind":"content","eyebrow":"5 of 8"},{"section":"Concept cycle 5","title":"Rational domains and vertical asymptotes: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"polynomial and rational behaviour\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M35 190 C95 35,155 230,225 78 S355 50,480 200\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"225\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">polynomial and rational behaviour</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for rational domains and vertical asymptotes?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 5","title":"Worked example: Rational domains and vertical asymptotes","html":"<div class=\"worked\"><h2>State the domain and vertical asymptote of R(x).</h2><ol class=\"method\"><li>The denominator is zero at x=4.</li><li>Exclude x=4 from the domain.</li><li>The vertical asymptote is x=4.</li></ol><div class=\"formula-panel\">\\[R(x)=\\frac{3x+2}{x-4}\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 5","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>State the domain and vertical asymptotes of h(x)=5/[(x+2)(x−7)].</b></div><textarea class=\"student-note tall\" data-note=\"turn-5\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">Domain excludes −2 and 7; asymptotes x=−2 and x=7.</div></details></div>","kind":"content","eyebrow":"Rational domains and vertical asymptotes"},{"section":"Concept cycle 5","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“A vertical asymptote is a y-value.”</p><h3>Repair</h3><p>A vertical asymptote has equation x=constant.</p></div></div>","kind":"content","eyebrow":"Rational domains and vertical asymptotes"},{"section":"Concept cycle 6","title":"Horizontal behaviour and holes","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>For equal numerator and denominator degree, the horizontal asymptote is the ratio of leading coefficients. A cancelled factor creates a removable hole, not a vertical asymptote.</p></article><div class=\"formula-panel\">\\[\\frac{(x-2)(x+1)}{(x-2)(x-5)}=\\frac{x+1}{x-5},\\ x\\ne2\\]</div></div>","kind":"content","eyebrow":"6 of 8"},{"section":"Concept cycle 6","title":"Horizontal behaviour and holes: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"polynomial and rational behaviour\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M35 190 C95 35,155 230,225 78 S355 50,480 200\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"225\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">polynomial and rational behaviour</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for horizontal behaviour and holes?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 6","title":"Worked example: Horizontal behaviour and holes","html":"<div class=\"worked\"><h2>Identify the hole and asymptote of the displayed function.</h2><ol class=\"method\"><li>The cancelled factor excludes x=2.</li><li>Substitute x=2 into the simplified rule: y=−1.</li><li>Hole at (2,−1); vertical asymptote x=5.</li></ol><div class=\"formula-panel\">\\[\\frac{(x-2)(x+1)}{(x-2)(x-5)}=\\frac{x+1}{x-5},\\ x\\ne2\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 6","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Find the horizontal asymptote of (4x²−1)/(2x²+7).</b></div><textarea class=\"student-note tall\" data-note=\"turn-6\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">y=4/2=2.</div></details></div>","kind":"content","eyebrow":"Horizontal behaviour and holes"},{"section":"Concept cycle 6","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“Cancelling a factor restores the excluded input.”</p><h3>Repair</h3><p>The original expression still excludes that input, leaving a hole.</p></div></div>","kind":"content","eyebrow":"Horizontal behaviour and holes"},{"section":"Concept cycle 7","title":"Direct and inverse variation","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Direct variation has y=kxⁿ; inverse variation has y=k/xⁿ. A constant product or constant ratio can reveal the structure.</p></article><div class=\"formula-panel\">\\[y=kx^n\\quad\\text{or}\\quad y=\\frac{k}{x^n}\\]</div></div>","kind":"content","eyebrow":"7 of 8"},{"section":"Concept cycle 7","title":"Direct and inverse variation: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"polynomial and rational behaviour\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M35 190 C95 35,155 230,225 78 S355 50,480 200\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"225\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">polynomial and rational behaviour</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for direct and inverse variation?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 7","title":"Worked example: Direct and inverse variation","html":"<div class=\"worked\"><h2>Given y varies inversely as x² and y=12 when x=3, find the model.</h2><ol class=\"method\"><li>Write y=k/x².</li><li>12=k/9, so k=108.</li><li>y=108/x².</li></ol><div class=\"formula-panel\">\\[y=kx^n\\quad\\text{or}\\quad y=\\frac{k}{x^n}\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 7","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>y varies directly as x³ and y=40 when x=2. Find y when x=5.</b></div><textarea class=\"student-note tall\" data-note=\"turn-7\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">k=5, so y=5x³ and y(5)=625.</div></details></div>","kind":"content","eyebrow":"Direct and inverse variation"},{"section":"Concept cycle 7","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“Inverse variation means y=−kx.”</p><h3>Repair</h3><p>Inverse describes reciprocal dependence, not negative gradient.</p></div></div>","kind":"content","eyebrow":"Direct and inverse variation"},{"section":"Concept cycle 8","title":"Selecting and constraining non-linear models","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Model selection combines shape, residual evidence, parameter meaning and contextual limits. A flexible curve is not automatically a defensible model.</p></article><div class=\"formula-panel\">\\[\\text{fit} + \\text{interpretability} + \\text{valid domain}\\]</div></div>","kind":"content","eyebrow":"8 of 8"},{"section":"Concept cycle 8","title":"Selecting and constraining non-linear models: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"polynomial and rational behaviour\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M35 190 C95 35,155 230,225 78 S355 50,480 200\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"310\" y1=\"25\" x2=\"310\" y2=\"225\" stroke=\"#177E89\" stroke-width=\"3\" stroke-dasharray=\"8 7\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">polynomial and rational behaviour</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for selecting and constraining non-linear models?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 8","title":"Worked example: Selecting and constraining non-linear models","html":"<div class=\"worked\"><h2>A rational model predicts infinite demand at price QAR 20. Explain why this is a warning.</h2><ol class=\"method\"><li>The model has a vertical asymptote at a feasible price.</li><li>Real demand cannot become infinite.</li><li>The formula should be restricted or replaced near that input.</li></ol><div class=\"formula-panel\">\\[\\text{fit} + \\text{interpretability} + \\text{valid domain}\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 8","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>A cubic fits 8 data points exactly but predicts negative population after year 12. Comment on its use for long-term forecasting.</b></div><textarea class=\"student-note tall\" data-note=\"turn-8\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">It may interpolate well but is unreliable for extrapolation because the prediction is impossible and the fitted form lacks long-term justification.</div></details></div>","kind":"content","eyebrow":"Selecting and constraining non-linear models"},{"section":"Concept cycle 8","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“The model with the highest degree is always best.”</p><h3>Repair</h3><p>Complexity can overfit data and weaken interpretation.</p></div></div>","kind":"content","eyebrow":"Selecting and constraining non-linear models"},{"section":"Technology laboratory","title":"Interactive laboratory","html":"<div class=\"lab\"><h2>Change a parameter. Predict first. Test second.</h2><p>Use tables and graphing tools to locate zeros and asymptotes, then verify each feature from the algebraic structure and intended domain.</p><div id=\"lesson-lab\" data-lab=\"2.3\"></div></div>","kind":"lab","eyebrow":"Technology with purpose"},{"section":"Technology laboratory","title":"GDC workflow","html":"<div class=\"workflow\"><div><b>1</b><span>Define variables and the valid domain.</span></div><div><b>2</b><span>Enter the model accurately.</span></div><div><b>3</b><span>Choose a window or list that reveals relevant behaviour.</span></div><div><b>4</b><span>Use trace, intersect, regression or solve.</span></div><div><b>5</b><span>Verify and interpret the output.</span></div></div>","kind":"content","eyebrow":"Repeatable process"},{"section":"Technology laboratory","title":"Interpreting calculator output","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Raw output</h2><p>A decimal, regression equation or graph feature is not yet a complete answer.</p></article><article class=\"focus-card\"><h2>IB response</h2><p>State the method, round appropriately, include units, select the contextual solution and explain what it means.</p></article></div>","kind":"content","eyebrow":"Technology → mathematics → context"},{"section":"Technology laboratory","title":"Precision and validation","html":"<div class=\"callout\"><b>Avoid premature rounding.</b> Store or retain full-precision values until the final line. Then test the result in the original model and check whether it belongs to the domain.</div><textarea class=\"student-note\" data-note=\"technology-check\" placeholder=\"Write the validation check you would use for this lesson.\"></textarea>","kind":"content","eyebrow":"Reliable evidence"},{"section":"Case study","title":"Case-study brief","html":"<div class=\"investigation\"><h2>A response rises, levels, and then falls, while another quantity changes rapidly near a forbidden input. What model structures explain these different behaviours?</h2><p>Build a model, make at least two assumptions, use technology, and identify evidence that could reject your model.</p></div>","kind":"content","eyebrow":"Mini investigation"},{"section":"Case study","title":"Data and model choice","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Evidence</h2><p>Use numerical, graphical and contextual information. Look for constant differences, ratios, turning points, asymptotes, residual structure or restrictions.</p></article><article class=\"focus-card\"><h2>Choice</h2><p>Select the simplest defensible model. A more complex model requires stronger evidence and clearer parameter interpretation.</p></article></div>","kind":"content","eyebrow":"Model selection"},{"section":"Case study","title":"Decision and interpretation","html":"<div class=\"student-turn\"><h2>Write the decision sentence</h2><p>“According to the model, … because … . This conclusion is valid for … and assumes … .”</p><textarea class=\"student-note tall\" data-note=\"case-decision\" placeholder=\"Complete the sentence for the inquiry context.\"></textarea></div>","kind":"content","eyebrow":"Communicate like an IB student"},{"section":"Case study","title":"Evaluate and extend","html":"<div class=\"reflection-grid\"><div><h2>Validity</h2><p>Does the model reproduce known data and respect physical limits?</p></div><div><h2>Sensitivity</h2><p>How much does the conclusion change when inputs or parameters change?</p></div><div><h2>Extension</h2><p>What additional data or alternative model would strengthen the decision?</p></div></div>","kind":"content","eyebrow":"Reflection is mathematics"},{"section":"Communication","title":"Full-mark response checklist","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"comm-1\"><span>I used the command term at the required depth.</span></label><label><input type=checkbox data-reflect=\"comm-2\"><span>I showed the equation, substitution or technology evidence.</span></label><label><input type=checkbox data-reflect=\"comm-3\"><span>I used correct notation, units and rounding.</span></label><label><input type=checkbox data-reflect=\"comm-4\"><span>I interpreted the result and addressed restrictions.</span></label><label><input type=checkbox data-reflect=\"comm-5\"><span>I evaluated assumptions when the question required judgment.</span></label></div>","kind":"content","eyebrow":"Before submitting"},{"section":"Communication","title":"Theory of Knowledge connection","html":"<div class=\"explain-prompt\"><h2>When does a useful model count as knowledge?</h2><p>Discuss whether predictive accuracy, explanatory mechanism, transparent assumptions and reproducibility contribute differently to trust.</p><textarea class=\"student-note tall\" data-note=\"tok\" placeholder=\"Write a claim, counterclaim and example.\"></textarea></div>","kind":"content","eyebrow":"TOK"},{"section":"Communication","title":"Internal assessment connection","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Possible exploration move</h2><p>Collect or source data, justify a function family, estimate parameters, analyse residuals and discuss limitations.</p></article><article class=\"focus-card\"><h2>Personal engagement</h2><p>Make a mathematical decision in a context you genuinely understand; do not merely reproduce calculator output.</p></article></div>","kind":"content","eyebrow":"IA thinking"},{"section":"Communication","title":"Exam strategy","html":"<div class=\"workflow\"><div><b>Read</b><span>Underline command terms, domain and requested precision.</span></div><div><b>Plan</b><span>Choose algebra, graph, table or regression deliberately.</span></div><div><b>Execute</b><span>Record method and retain full precision.</span></div><div><b>Interpret</b><span>Return to context and units.</span></div><div><b>Check</b><span>Substitute, compare or inspect residuals.</span></div></div>","kind":"content","eyebrow":"Five moves"},{"section":"Closure","title":"Mixed exit ticket","html":"<div class=\"exit-grid\"><div><b>Represent</b><span>Give two representations of one idea from Polynomial and Rational Models.</span></div><div><b>Calculate</b><span>Create and solve a numerical example.</span></div><div><b>Interpret</b><span>Explain a parameter or feature with units.</span></div><div><b>Evaluate</b><span>State one assumption and one limitation.</span></div></div><textarea class=\"student-note tall\" data-note=\"exit\" placeholder=\"Complete all four prompts.\"></textarea>","kind":"content","eyebrow":"Synthesis"},{"section":"Closure","title":"Mastery checklist","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"master-2.3-0\"><span>Interpret polynomial degree, zeros and end behaviour from equations and graphs.</span></label><label><input type=checkbox data-reflect=\"master-2.3-1\"><span>Use factors and multiplicity to connect algebraic structure with graph behaviour.</span></label><label><input type=checkbox data-reflect=\"master-2.3-2\"><span>Determine domains and asymptotes of rational models and interpret them contextually.</span></label><label><input type=checkbox data-reflect=\"master-2.3-3\"><span>Recognize direct, inverse and power variation and use technology to estimate parameters.</span></label></div>","kind":"content","eyebrow":"Can you do this independently?"},{"section":"Closure","title":"Next route","html":"<div class=\"connection-grid\"><button class=\"primary-btn route-jump\" data-go=\"practice\">Practice Studio · 60 questions</button><button class=\"secondary-btn route-jump\" data-go=\"exam\">IB Tasks · 3 extended responses</button><button class=\"secondary-btn route-jump\" data-go=\"quiz\">Timed Quiz · 12 questions</button><button class=\"secondary-btn route-jump\" data-go=\"review\">Mastery review</button></div>","kind":"content","eyebrow":"Choose evidence"},{"section":"Closure","title":"Lesson complete","html":"<div class=\"launch-panel\"><h2>Polynomial and Rational Models</h2><p>You have completed the Learn route. Use Practice Studio, IB Tasks and the independent quiz to turn familiarity into durable evidence.</p><button class=\"primary-btn route-jump\" data-go=\"review\">Open mastery and mark completion</button></div>","kind":"content","eyebrow":"Bridge to practice"}],"practice":[{"id":"IBAI-2.3-P01","level":"Foundation","prompt":"State the degree of \\(f(x)=7x^5-3x^2+9\\).","answer":"\\(5\\)","solution":"The highest exponent is 5.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"number","value":5.0,"tolerance":5e-05}},{"id":"IBAI-2.3-P02","level":"Foundation","prompt":"Describe the end behaviour of \\(f(x)=2x^4-5x\\).","answer":"Both ends rise: \\(f(x)\\to\\infty\\) as \\(x\\to\\pm\\infty\\).","solution":"The leading term 2x⁴ has even degree and positive coefficient.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["both ends up","f(x)->infinity as x->plus or minus infinity","positive even"]}},{"id":"IBAI-2.3-P03","level":"Foundation","prompt":"State the zeros of \\(g(x)=x(x-4)(x+7)\\).","answer":"\\(x=-7,0,4\\)","solution":"Set each factor equal to zero.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["-7,0,4","x=-7,0,4","{-7,0,4}"]}},{"id":"IBAI-2.3-P04","level":"Foundation","prompt":"If \\(x-3\\) is a factor of f, write down one zero.","answer":"\\(3\\)","solution":"The factor theorem gives f(3)=0.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"check":{"mode":"number","value":3.0,"tolerance":3.0000000000000004e-05}},{"id":"IBAI-2.3-P05","level":"Foundation","prompt":"At which zero does \\(y=(x+2)^2(x-5)\\) touch the x-axis?","answer":"x=−2","solution":"The zero −2 has even multiplicity 2.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["x=−2","x=5","Both","Neither"],"correct":0,"check":{"mode":"choice","value":0}},{"id":"IBAI-2.3-P06","level":"Foundation","prompt":"At which zero does \\(y=(x-1)^3(x+4)^2\\) cross the x-axis?","answer":"x=1 only","solution":"The zero 1 has odd multiplicity 3.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["x=1 only","x=−4 only","Both","Neither"],"correct":0,"check":{"mode":"choice","value":0}},{"id":"IBAI-2.3-P07","level":"Foundation","prompt":"State the domain of \\(R(x)=\\frac{2x+1}{x-6}\\).","answer":"\\(x\\ne6\\)","solution":"The denominator cannot be zero.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["x!=6","x ≠ 6","(-infinity,6) union (6,infinity)"]}},{"id":"IBAI-2.3-P08","level":"Foundation","prompt":"State the vertical asymptote of \\(y=4/(x+9)\\).","answer":"\\(x=-9\\)","solution":"The denominator is zero at x=−9.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"number","value":-9.0,"tolerance":9e-05}},{"id":"IBAI-2.3-P09","level":"Foundation","prompt":"State the horizontal asymptote of \\(y=(6x^2+1)/(3x^2-5)\\).","answer":"\\(y=2\\)","solution":"Equal degrees: ratio of leading coefficients 6/3=2.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"number","value":2.0,"tolerance":2e-05}},{"id":"IBAI-2.3-P10","level":"Foundation","prompt":"Identify the hole in \\(y=\\frac{(x-4)(x+2)}{(x-4)(x-1)}\\).","answer":"Hole at \\((4,2)\\)","solution":"Cancel to (x+2)/(x−1); at x=4 the limiting value is 2.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"check":{"mode":"text","accepted":["(4,2)","x=4 y=2","hole at (4,2)"]}},{"id":"IBAI-2.3-P11","level":"Foundation","prompt":"y varies directly as x². If y=45 when x=3, find k in \\(y=kx^2\\).","answer":"\\(5\\)","solution":"45=9k.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":5.0,"tolerance":5e-05}},{"id":"IBAI-2.3-P12","level":"Foundation","prompt":"y varies inversely as x. If y=8 when x=5, find y when x=20.","answer":"\\(2\\)","solution":"yx=40, so y=40/20=2.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":2.0,"tolerance":2e-05}},{"id":"IBAI-2.3-P13","level":"Foundation","prompt":"For \\(f(x)=x^3-2x+6\\), calculate f(2).","answer":"\\(10\\)","solution":"8−4+6=10.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":10.0,"tolerance":0.0001}},{"id":"IBAI-2.3-P14","level":"Foundation","prompt":"What is the maximum number of turning points of a degree-4 polynomial?","answer":"3","solution":"A degree-n polynomial has at most n−1 turning points.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"choices":["2","3","4","5"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.3-P15","level":"Foundation","prompt":"Which model represents inverse-square variation?","answer":"y=k/x²","solution":"Inverse-square means reciprocal of x².","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["y=kx²","y=k/x²","y=kx","y=k−x²"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.3-P16","level":"Application","prompt":"The volume of a family of similar cubes varies directly as side length cubed. A cube of side 4 cm has volume 64 cm³. Find the volume when the side is 7 cm.","answer":"\\(343\\text{ cm}^3\\)","solution":"V=ks³ and k=1, so V=7³.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":343.0,"tolerance":0.0034300000000000003}},{"id":"IBAI-2.3-P17","level":"Application","prompt":"Light intensity varies inversely as the square of distance. Intensity is 180 units at 2 m. Find the intensity at 6 m.","answer":"\\(20\\)","solution":"k=180(2²)=720; I=720/36=20.","marks":4,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":20.0,"tolerance":0.0002}},{"id":"IBAI-2.3-P18","level":"Application","prompt":"Travel time is modelled by \\(T(v)=360/v\\) minutes for speed v km/h. Find T(80).","answer":"\\(4.5\\text{ min}\\)","solution":"360/80=4.5.","marks":2,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":4.5,"tolerance":4.5e-05}},{"id":"IBAI-2.3-P19","level":"Application","prompt":"A rational cost-per-user model is \\(C(n)=1200/n+18\\). Find C(75).","answer":"QAR \\(34\\)","solution":"1200/75+18=16+18.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":34.0,"tolerance":0.00034}},{"id":"IBAI-2.3-P20","level":"Application","prompt":"Interpret the horizontal asymptote y=18 in \\(C(n)=1200/n+18\\).","answer":"As the number of users grows, the cost per user approaches QAR 18.","solution":"The fixed shared cost becomes negligible.","marks":3,"calculator":"No GDC required","command":"Interpret","hint":"","tags":[],"check":{"mode":"text","accepted":["approaches 18","minimum long-run cost","cost per user tends to 18"]}},{"id":"IBAI-2.3-P21","level":"Application","prompt":"A cubic profit model is \\(P(x)=-x^3+12x^2-20x\\). Calculate P(5).","answer":"\\(75\\)","solution":"P(5)=−125+300−100=75.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":75.0,"tolerance":0.00075}},{"id":"IBAI-2.3-P22","level":"Application","prompt":"A response model is \\(R(t)=0.4t^3-6t^2+18t+12\\). Find R(3).","answer":"\\(22.8\\)","solution":"R(3)=10.8−54+54+12=22.8.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":22.8,"tolerance":0.01}},{"id":"IBAI-2.3-P23","level":"Application","prompt":"The number of items per worker is \\(N(w)=900/w\\). Find the number of workers needed for 45 items per worker.","answer":"\\(20\\)","solution":"Solve 900/w=45.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":20.0,"tolerance":0.0002}},{"id":"IBAI-2.3-P24","level":"Application","prompt":"A pollutant model is \\(Q(t)=500/(t+4)\\). Find t when Q=25.","answer":"\\(16\\)","solution":"500/(t+4)=25, so t+4=20.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":16.0,"tolerance":0.00016}},{"id":"IBAI-2.3-P25","level":"Application","prompt":"A rational model has a vertical asymptote at a feasible input of 12 customers. Explain one concern.","answer":"The model becomes undefined or unbounded at a realistic input, so it cannot be trusted near 12 customers.","solution":"A real system cannot usually support an infinite response.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["infinite prediction","undefined at 12","not realistic"]}},{"id":"IBAI-2.3-P26","level":"Application","prompt":"A direct-variation model is \\(E=ks^{1.5}\\). If E=80 when s=4, find k.","answer":"\\(10\\)","solution":"4^1.5=8, so k=80/8=10.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":10.0,"tolerance":0.0001}},{"id":"IBAI-2.3-P27","level":"Application","prompt":"A cylinder with fixed shape has volume proportional to the cube of its scale factor. If scale factor 1.5 gives volume 405 cm³, find the volume at scale factor 2.","answer":"\\(960\\text{ cm}^3\\)","solution":"k=405/1.5³=120; V=120(8)=960.","marks":4,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":960.0,"tolerance":0.009600000000000001}},{"id":"IBAI-2.3-P28","level":"Application","prompt":"A model \\(A(x)=2000/x+14\\) is used only for positive x. State a realistic reason for excluding x≤0.","answer":"The input represents a positive count or amount; x=0 is undefined and negative values have no contextual meaning.","solution":"Both mathematical and contextual restrictions apply.","marks":2,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["input count positive","division by zero","negative quantity impossible"]}},{"id":"IBAI-2.3-P29","level":"Application","prompt":"A polynomial revenue model has zeros at x=0 and x=60 and is \\(R(x)=5x(60-x)\\). Find the maximum revenue.","answer":"\\(4500\\)","solution":"The axis is x=30; R=5(30)(30)=4500.","marks":4,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":4500.0,"tolerance":0.045000000000000005}},{"id":"IBAI-2.3-P30","level":"Application","prompt":"A power model \\(y=2.4x^{-1.5}\\). Calculate y when x=9.","answer":"\\(0.0889\\)","solution":"9^1.5=27, so y=2.4/27.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":0.08888888888888889,"tolerance":0.0001}},{"id":"IBAI-2.3-P31","level":"Reasoning","prompt":"A polynomial has odd degree and positive leading coefficient. Which end behaviour is correct?","answer":"Left falls, right rises","solution":"Positive odd leading term behaves like x³.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["Both ends rise","Left falls, right rises","Left rises, right falls","Both ends fall"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.3-P32","level":"Reasoning","prompt":"Explain why a cancelled factor creates a hole rather than restoring the point.","answer":"The original denominator was zero at that input, so the original function remains undefined even after algebraic simplification.","solution":"The simplified rule gives only the limiting value.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["original domain excludes","undefined in original","removable discontinuity"]}},{"id":"IBAI-2.3-P33","level":"Reasoning","prompt":"A residual plot for a cubic fit shows random scatter, while a quadratic fit shows a strong S-pattern. Which is better supported?","answer":"Cubic","solution":"Random residuals support the cubic more strongly, provided context and complexity are acceptable.","marks":2,"calculator":"No GDC required","command":"Comment","hint":"","tags":[],"choices":["Quadratic","Cubic","Both identical","Neither can be compared"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.3-P34","level":"Reasoning","prompt":"A rational model tends to y=7 as x increases. Interpret this in context.","answer":"The predicted output approaches 7 units for large inputs, although it may not equal 7 at any finite input.","solution":"State the quantity and units when known.","marks":2,"calculator":"No GDC required","command":"Interpret","hint":"","tags":[],"check":{"mode":"text","accepted":["approaches 7","limiting value 7","long-run level"]}},{"id":"IBAI-2.3-P35","level":"Reasoning","prompt":"Which feature cannot occur for a polynomial?","answer":"A vertical asymptote","solution":"Polynomials are defined and continuous for all real x, so no vertical asymptotes.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["A turning point","A repeated zero","A vertical asymptote","An x-intercept"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.3-P36","level":"Reasoning","prompt":"A function behaves like 1/x² for large |x|. Which horizontal asymptote is expected?","answer":"y=0","solution":"1/x² tends to zero.","marks":2,"calculator":"No GDC required","command":"Deduce","hint":"","tags":[],"choices":["y=1","x=0","y=0","None"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.3-P37","level":"Reasoning","prompt":"Explain why a degree-8 polynomial can overfit a data set of 9 points.","answer":"It can pass through every point and capture random noise rather than the underlying mechanism, leading to unstable predictions.","solution":"Fit alone is not enough.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["passes exactly","captures noise","poor extrapolation"]}},{"id":"IBAI-2.3-P38","level":"Reasoning","prompt":"If y varies directly as x³, what happens to y when x doubles?","answer":"It is multiplied by 8","solution":"(2x)³=8x³.","marks":2,"calculator":"No GDC required","command":"Deduce","hint":"","tags":[],"choices":["It doubles","It quadruples","It is multiplied by 8","It halves"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.3-P39","level":"Reasoning","prompt":"If y varies inversely as x², what happens when x triples?","answer":"y is divided by 9","solution":"The reciprocal square introduces a factor 1/9.","marks":2,"calculator":"No GDC required","command":"Deduce","hint":"","tags":[],"choices":["y triples","y is divided by 3","y is divided by 9","y is multiplied by 9"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.3-P40","level":"Reasoning","prompt":"Why should a vertical asymptote inside a contextual domain be investigated before using the model?","answer":"The model becomes undefined or unbounded at a feasible input, which may signal a wrong form or a missing physical constraint.","solution":"The asymptote may be mathematically real but contextually impossible.","marks":3,"calculator":"No GDC required","command":"Justify","hint":"","tags":[],"check":{"mode":"text","accepted":["unbounded","undefined","impossible prediction"]}},{"id":"IBAI-2.3-P41","level":"Reasoning","prompt":"For y=(x−4)^4(x+2), at which root does the sign change?","answer":"x=−2 only","solution":"Odd multiplicity at −2 changes sign; even multiplicity at 4 does not.","marks":2,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"choices":["x=4 only","x=−2 only","Both","Neither"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.3-P42","level":"Reasoning","prompt":"A model has domain x>0 and vertical asymptote x=0. Explain why the asymptote may represent a boundary rather than a possible input.","answer":"The model can approach x=0 from positive values but x=0 is not allowed, so the asymptote describes boundary behaviour.","solution":"Do not interpret an excluded input as an observed state.","marks":2,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["x=0 excluded","boundary","approach not reach"]}},{"id":"IBAI-2.3-P43","level":"Reasoning","prompt":"Which evidence most strongly suggests direct variation y=kx?","answer":"A straight line through the origin","solution":"Direct proportionality requires y/x constant and graph through origin.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["A straight line with non-zero intercept","A straight line through the origin","A U-shaped curve","A horizontal line"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.3-P44","level":"Reasoning","prompt":"A rational function has numerator degree less than denominator degree. What is the horizontal asymptote?","answer":"y=0","solution":"The denominator grows faster, so the ratio tends to zero.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"choices":["y=0","x=0","Ratio of constant terms","No asymptote"],"correct":0,"check":{"mode":"choice","value":0}},{"id":"IBAI-2.3-P45","level":"Reasoning","prompt":"A polynomial model predicts negative sales beyond year 15. Comment on extrapolation.","answer":"The model may fit the observed interval but is not defensible beyond it because negative sales are impossible; restrict or replace the model.","solution":"Contextual feasibility limits extrapolation.","marks":3,"calculator":"No GDC required","command":"Comment","hint":"","tags":[],"check":{"mode":"text","accepted":["not valid","negative impossible","restrict domain"]}},{"id":"IBAI-2.3-P46","level":"Challenge","prompt":"A cubic has zeros −2, 1 and 5 and passes through (0,20). Find its leading coefficient.","answer":"\\(2\\)","solution":"20=a(2)(−1)(−5)=10a, so a=2.","marks":4,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":2.0,"tolerance":2e-05}},{"id":"IBAI-2.3-P47","level":"Challenge","prompt":"Construct a polynomial of least degree with zeros 3 (multiplicity 2) and −4 (multiplicity 1) and y-intercept 72.","answer":"\\(y=2(x-3)^2(x+4)\\)","solution":"At x=0, 72=a(9)(4)=36a, so a=2.","marks":5,"calculator":"No GDC required","command":"Construct","hint":"","tags":[],"check":{"mode":"text","accepted":["(x-3)^2(x+4)","2(x-3)^2(x+4)","y=2(x-3)^2(x+4)"]}},{"id":"IBAI-2.3-P48","level":"Challenge","prompt":"Solve \\(\\frac{3x+1}{x-2}=7\\).","answer":"\\(3.75\\)","solution":"3x+1=7x−14, so 15=4x.","marks":4,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":3.75,"tolerance":3.7500000000000003e-05}},{"id":"IBAI-2.3-P49","level":"Challenge","prompt":"State the domain and hole of \\(f(x)=\\frac{x^2-9}{x^2-x-6}\\).","answer":"Domain excludes \\(x=-2,3\\); hole at \\((3,6/5)\\).","solution":"Factor: (x−3)(x+3)/[(x−3)(x+2)]. The remaining asymptote is x=−2.","marks":5,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"check":{"mode":"text","accepted":["x!=-2,3 hole at 3,6/5","domain excludes -2 and 3; hole (3,6/5)"]}},{"id":"IBAI-2.3-P50","level":"Challenge","prompt":"Find the horizontal asymptote of \\(R(x)=\\frac{-6x^3+2x}{3x^3+5}\\).","answer":"\\(y=-2\\)","solution":"Ratio of leading coefficients −6/3=−2.","marks":3,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":-2.0,"tolerance":2e-05}},{"id":"IBAI-2.3-P51","level":"Challenge","prompt":"y varies inversely as x^(3/2). If y=16 when x=4, find y when x=25.","answer":"\\(1.024\\)","solution":"k=16·4^(3/2)=128; y=128/125=1.024.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":1.024,"tolerance":0.001}},{"id":"IBAI-2.3-P52","level":"Challenge","prompt":"A direct power model y=kx^n has y=12 at x=2 and y=96 at x=4. Find n.","answer":"\\(3\\)","solution":"96/12=(4/2)^n gives 8=2^n, so n=3.","marks":5,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":3.0,"tolerance":3.0000000000000004e-05}},{"id":"IBAI-2.3-P53","level":"Challenge","prompt":"Determine the range of \\(f(x)=\\frac{2x+3}{x-1}\\).","answer":"\\(y\\ne2\\)","solution":"Solve y=(2x+3)/(x−1) for x: x=(y+3)/(y−2), which fails only at y=2.","marks":5,"calculator":"GDC permitted","command":"Determine","hint":"","tags":[],"check":{"mode":"text","accepted":["y!=2","(-infinity,2) union (2,infinity)","y ≠ 2"]}},{"id":"IBAI-2.3-P54","level":"Challenge","prompt":"The graph of \\(y=x^3-4x\\) intersects the x-axis at three points. Find the sum of the squares of the roots.","answer":"\\(8\\)","solution":"Roots are −2,0,2; squares sum to 4+0+4.","marks":4,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":8.0,"tolerance":8e-05}},{"id":"IBAI-2.3-P55","level":"Challenge","prompt":"A rational model \\(C(n)=900/n+15\\) must be below 30. Find the smallest integer n.","answer":"\\(61\\)","solution":"900/n+15<30 gives n>60; smallest integer 61.","marks":4,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":61.0,"tolerance":0.0006100000000000001}},{"id":"IBAI-2.3-P56","level":"Challenge","prompt":"A polynomial has end behaviour down-left and down-right and exactly three real zeros counting multiplicity. Explain why the degree cannot be 3.","answer":"Both ends in the same direction require even degree, whereas a cubic has opposite end behaviour.","solution":"The polynomial may have degree 4 or higher even degree.","marks":4,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["even degree","both ends same","cubic opposite ends"]}},{"id":"IBAI-2.3-P57","level":"Challenge","prompt":"Find k so \\(f(x)=x^3+kx^2-4x+6\\) has x=2 as a zero.","answer":"\\(-1.5\\)","solution":"f(2)=8+4k−8+6=4k+6=0, so k=−1.5.","marks":4,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"check":{"mode":"number","value":-1.5,"tolerance":1.5000000000000002e-05}},{"id":"IBAI-2.3-P58","level":"Challenge","prompt":"A model \\(P(t)=t^3-11t^2+24t\\) has a zero at t=0. Find the sum of the other two zeros.","answer":"\\(11\\)","solution":"Factor t(t²−11t+24)=t(t−3)(t−8).","marks":4,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"number","value":11.0,"tolerance":0.00011}},{"id":"IBAI-2.3-P59","level":"Challenge","prompt":"A curve y=a/(x−2)+5 passes through (6,11). Find a.","answer":"\\(24\\)","solution":"11= a/4+5, so a=24.","marks":3,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":24.0,"tolerance":0.00024000000000000003}},{"id":"IBAI-2.3-P60","level":"Challenge","prompt":"Compare \\(y=600/x\\) and \\(y=600/x^2\\) for x>1. Which decreases faster and why?","answer":"The inverse-square model decreases faster because doubling x divides the output by 4 rather than 2.","solution":"The power controls the rate of reciprocal decay.","marks":4,"calculator":"No GDC required","command":"Compare","hint":"","tags":[],"check":{"mode":"text","accepted":["600/x^2","inverse square","larger exponent"]}}],"quiz":[{"id":"IBAI-2.3-Q01","level":"Quiz","prompt":"State the degree of 4x⁶−x³+2.","answer":"\\(6\\)","solution":"Highest exponent.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"number","value":6.0,"tolerance":6.000000000000001e-05}},{"id":"IBAI-2.3-Q02","level":"Quiz","prompt":"Describe the end behaviour of −2x⁴+3x.","answer":"Both ends fall to \\(-\\infty\\).","solution":"Negative even leading term.","marks":2,"calculator":"No GDC required","command":"Describe","hint":"","tags":[],"check":{"mode":"text","accepted":["both ends down","f(x)->-infinity"]}},{"id":"IBAI-2.3-Q03","level":"Quiz","prompt":"State the zeros of x(x+5)(x−2).","answer":"\\(-5,0,2\\)","solution":"Factor zeros.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["-5,0,2","x=-5,0,2"]}},{"id":"IBAI-2.3-Q04","level":"Quiz","prompt":"At which root does (x−4)²(x+1)³ touch the axis?","answer":"4","solution":"Even multiplicity at 4.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["4","−1","Both","Neither"],"correct":0,"check":{"mode":"choice","value":0}},{"id":"IBAI-2.3-Q05","level":"Quiz","prompt":"State the domain of (x+2)/(x²−16).","answer":"\\(x\\ne-4,4\\)","solution":"Denominator zeros.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["x!=-4,4","exclude -4 and 4"]}},{"id":"IBAI-2.3-Q06","level":"Quiz","prompt":"Find the horizontal asymptote of (9x²+1)/(3x²−7).","answer":"\\(y=3\\)","solution":"Leading coefficient ratio.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":3.0,"tolerance":3.0000000000000004e-05}},{"id":"IBAI-2.3-Q07","level":"Quiz","prompt":"y varies inversely as x. If y=15 when x=4, find y when x=10.","answer":"\\(6\\)","solution":"yx=60.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":6.0,"tolerance":6.000000000000001e-05}},{"id":"IBAI-2.3-Q08","level":"Quiz","prompt":"y varies directly as x² and y=18 when x=3. Find y when x=7.","answer":"\\(98\\)","solution":"k=2; y=2(49).","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":98.0,"tolerance":0.0009800000000000002}},{"id":"IBAI-2.3-Q09","level":"Quiz","prompt":"Explain why a polynomial cannot have a vertical asymptote.","answer":"A polynomial is defined and continuous for every real x.","solution":"No input produces division by zero.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["defined all real","continuous","no denominator"]}},{"id":"IBAI-2.3-Q10","level":"Quiz","prompt":"Solve (2x−1)/(x+3)=3.","answer":"\\(-10\\)","solution":"2x−1=3x+9.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":-10.0,"tolerance":0.0001}},{"id":"IBAI-2.3-Q11","level":"Quiz","prompt":"Identify the hole in (x²−1)/(x−1).","answer":"\\((1,2)\\)","solution":"Simplifies to x+1 but x=1 remains excluded.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"check":{"mode":"text","accepted":["(1,2)","x=1 y=2"]}},{"id":"IBAI-2.3-Q12","level":"Quiz","prompt":"A high-degree polynomial fits all data exactly but oscillates wildly between points. Name the main concern.","answer":"Overfitting","solution":"The model captures noise and may generalize poorly.","marks":3,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["overfitting","overfit"]}}],"exam":[{"id":"U2-2.3-T1","style":"Paper 2 · polynomial model","title":"Open box volume","calculator":"GDC expected","total_marks":10,"context":"A 30 cm by 20 cm sheet has squares of side x cm removed from each corner and is folded into an open box. The volume is \\(V(x)=x(30-2x)(20-2x)\\).","parts":[{"label":"a","prompt":"State the physical domain of x.","marks":2,"answer":"\\(0<x<10\\).","markscheme":"A1 positive cut; A1 smallest half-dimension."},{"label":"b","prompt":"Expand V(x).","marks":3,"answer":"\\(V(x)=4x^3-100x^2+600x\\).","markscheme":"M1 multiply binomials; A1 intermediate; A1 final."},{"label":"c","prompt":"Use technology to find the value of x that maximizes the volume.","marks":3,"answer":"\\(x\\approx3.92\\) cm.","markscheme":"M1 graph/solve derivative or maximum; A1 x; A1 domain check."},{"label":"d","prompt":"Calculate the maximum volume and report it to three significant figures.","marks":2,"answer":"\\(V\\approx1056\\text{ cm}^3\\), so \\(1.06\\times10^3\\text{ cm}^3\\).","markscheme":"M1 substitution; A1 3 sf and units."}]},{"id":"U2-2.3-T2","style":"Paper 2 · rational model","title":"Average cost of production","calculator":"GDC expected","total_marks":10,"context":"The average cost per item is modelled by \\(C(n)=18+\\frac{2400}{n}\\) QAR, where n is the number of items produced.","parts":[{"label":"a","prompt":"State the contextual domain.","marks":2,"answer":"Positive integers \\(n\\ge1\\).","markscheme":"A1 positive; A1 discrete integer context."},{"label":"b","prompt":"Calculate C(50) and C(300).","marks":2,"answer":"C(50)=66 QAR; C(300)=26 QAR.","markscheme":"A1 each value."},{"label":"c","prompt":"State and interpret the horizontal asymptote.","marks":3,"answer":"y=18; average cost approaches 18 QAR per item as production grows, representing the variable-cost floor.","markscheme":"A1 asymptote; A1 approach; A1 context."},{"label":"d","prompt":"Solve C(n)<30 and interpret the result.","marks":3,"answer":"\\(n>200\\), so at least 201 items are required.","markscheme":"M1 inequality; A1 n>200; A1 integer interpretation."}]},{"id":"U2-2.3-T3","style":"Investigation · variation","title":"Light intensity model","calculator":"GDC expected","total_marks":10,"context":"A sensor records light intensity I at distances d from a lamp. A proposed model is \\(I=\\frac{k}{d^2}\\). At d=2.5 m, I=96 units.","parts":[{"label":"a","prompt":"Find k.","marks":2,"answer":"\\(k=600\\).","markscheme":"M1 substitute; A1 value."},{"label":"b","prompt":"Predict I at d=6 m.","marks":2,"answer":"\\(I=600/36\\approx16.7\\) units.","markscheme":"M1 substitution; A1 value."},{"label":"c","prompt":"Explain how a transformed plot could be used to test the model.","marks":3,"answer":"Plot I against \\(1/d^2\\); a straight line through the origin supports inverse-square variation.","markscheme":"A1 transformed variable; A1 linear expectation; R1 origin/fit."},{"label":"d","prompt":"State two reasons the model may fail at very small distances.","marks":3,"answer":"The lamp is not a point source; sensor saturation, reflections or geometry may dominate.","markscheme":"Any two valid limitations with contextual relevance."}]}],"counts":{"slides":64,"practice":60,"quiz":12,"exam":3},"rights":{"student_content":"Original ECHS-authored instructional and assessment content","private_bank_policy":"No source-bank prompt, canonical ID, provenance record or rights record is embedded in public lesson assets."}};
